def get_date_of_range_to_kwargs(asset, dt, frequency):
    """
    获取切片用的数据参数。
    主要是开始和结束范围区间
    分钟线: 一周范围
    日线: 一年范围
    :param asset: 合约对象
    :type asset: : AssetType
    
    :param dt: 查询时间
    :type dt: : datetime.date
    
    :param frequency: 频率
    :type frequency: :  str
    
    :return value: 参数集合
    :type: dict
    """
    from fly.common.tradingday_calendar import get_trading_day
    pre_trading_date = get_trading_day(-1).strftime('%Y%m%d')
    if frequency == Frequency.TICK.value:
        start_time = dt.strftime('%Y%m%d')
        end_time = dt.strftime('%Y%m%d')
    elif frequency[-1] == Frequency.MINUTE.value[-1]:
        dayweek = dt.weekday()
        _end_time = dt + tdl(days=6 - dayweek)
        start_time = (dt - tdl(days=dayweek)).strftime('%Y%m%d')
        end_time = _end_time.strftime('%Y%m%d')
        if type(_end_time) == datetime.datetime:
            _end_time_day = _end_time.date()
        else:
            _end_time_day = _end_time.to_pydatetime().date()
        today_date = datetime.date.today()
        if _end_time_day >= today_date:
            end_time = pre_trading_date
    elif frequency[-1] == Frequency.DAILY.value[-1]:
        start_time = dt.strftime('%Y0101')
        end_time = dt.strftime('%Y1231') if dt.strftime('%Y1231') < pre_trading_date else pre_trading_date
        return {'symbol': asset['symbol'], 'start_time': start_time, 'end_time': end_time, 'asset_type': asset['type'], 'frequency': frequency}
    else:
        start_time = dt.strftime('%Y0101')
        end_time = dt.strftime('%Y1231') if dt.strftime('%Y1231') < pre_trading_date else pre_trading_date
def get_date_of_range_to_kwargs_(asset, dt, frequency):
    """
    获取切片用的数据参数。
    主要是开始和结束范围区间
    分钟线: 一周范围
    日线: 一年范围
    :param asset: 合约对象
    :type asset: : AssetType

    :param dt: 查询时间
    :type dt: : datetime.date

    :param frequency: 频率
    :type frequency: :  str

    :return value: 参数集合
    :type: dict
    """
    if frequency == Frequency.TICK.value:
        start_time = dt.strftime('%Y%m%d')
        end_time = dt.strftime('%Y%m%d')
    elif frequency == Frequency.DAILY.value:
        start_time = '%s0101' % (dt.year - 1)
        end_time = dt.strftime('%Y1231') if dt.strftime('%Y1231') < time.strftime('%Y%m%d') else time.strftime('%Y%m%d')
        return {'symbol': asset['symbol'], 'start_time': start_time, 'end_time': end_time, 'asset_type': asset['type'], 'frequency': frequency}
    elif frequency[-1] == Frequency.MINUTE.value[-1]:
        dayweek = dt.weekday()
        start_time = (dt - tdl(days=dayweek)).strftime('%Y%m%d')
        end_time = (dt + tdl(days=6 - dayweek)).strftime('%Y%m%d')
    else:
        raise ValueError('Argument frequency not support')
