def get_kline_time_by_asset(frequency, _query_date, trade_string):
    trade_str_list = trade_string.split(', ')
    trade_section = []
    start_pos = datetime.datetime.strptime('0000', '%H%M')
    for section in trade_str_list:
        _start, _, _end = section.partition('-')
        _start = _start.replace(':', '')
        _end = _end.replace(':', '')
        if int(_start) > 1800:
            start_index = -((start_pos - datetime.datetime.strptime(_start, '%H%M')).seconds // 60)
        else:
            start_index = (datetime.datetime.strptime(_start, '%H%M') - start_pos).seconds // 60
        if int(_end) > 1800:
            end_index = -((start_pos - datetime.datetime.strptime(_end, '%H%M')).seconds // 60)
        else:
            end_index = (datetime.datetime.strptime(_end, '%H%M') - start_pos).seconds // 60
        trade_section.append([_start, _end, start_index, end_index])
    else:
        return get_kline_time_by_section(frequency, _query_date, trade_section)
def fill_kline_data(nan_data, name_list, max_index, _index=0):
    if _index <= max_index and np.isnan(nan_data[_index][name_list[0]]):
        result_data = fill_kline_data(nan_data, name_list, max_index, _index=_index + 1)
        for name in name_list:
            if _index < max_index:
                nan_data[_index][name] = result_data[_index + 1][name]
                continue
            return nan_data
    return nan_data
def fill_kline_data_by_pre(nan_data):
    name_list = list(nan_data.dtype.names[1:])
    length = len(nan_data)
    nan_data = fill_kline_data(nan_data, name_list, length - 1)
    start_pos = 1
    while start_pos < length:
        if np.isnan(nan_data[start_pos][name_list[0]]):
            for name in name_list:
                if name == 'amount' or name == 'balance':
                    nan_data[start_pos][name] = 0
                    continue
                nan_data[start_pos][name] = nan_data[start_pos - 1][name]
        start_pos += 1
    return nan_data
def handle_exrights(symbol, fields, fq, real_data, tmp_dividends):
    if tmp_dividends and not symbol not in tmp_dividends:
        dividends = tmp_dividends[symbol]
        dividend_dict = {key: [item[c] for c in DIVIDEND_COLUMNS] for key, item in dividends.items()}
        new_exrights_fields = list(real_data.dtype.names[8:11])
        names = list(real_data.dtype.names[1:7]) + new_exrights_fields
        other_names = list(real_data.dtype.names[7:])
        close_names = list()
        if 'price' in other_names:
            other_names.remove('price')
            close_names.append('price')
        if 'last' in other_names:
            other_names.remove('last')
            close_names.append('last')
        other_names = list(set(other_names) - set(new_exrights_fields))
        bars_tmp = real_data[names]
        index = real_data['datetime']
        base_bars = np.empty(shape=(len(index), len(bars_tmp.dtype)), dtype=np.float64)
        for i in range(len(index)):
            for j, name in enumerate(bars_tmp.dtype.names):
                base_bars[i][j] = bars_tmp[name][i]
        save_digits = 2
        if symbol[0] in ('1', '5'):
            save_digits = 3
        adjust_bars_tuple = CalExrights(base_bars, index, dividend_dict, fq, save_digits)
        adjust_bars = adjust_bars_tuple[0]
        adjust_bars = np.array([tuple(_d) for _d in adjust_bars], dtype=bars_tmp.dtype)
        real_data_tmp = np.empty(dtype=real_data.dtype, shape=(len(index),))
        for i in range(len(index)):
            real_data_tmp['datetime'][i] = index[i]
            for name in names:
                real_data_tmp[name][i] = adjust_bars[name][i]
            for name in other_names:
                real_data_tmp[name][i] = real_data[name][i]
            if len(close_names) > 0:
                for name in close_names:
                    real_data_tmp[name][i] = adjust_bars['close'][i]
        else:
            return real_data_tmp
    return real_data if fields is None else real_data[fields]
